fn validate_request(r:&IdsEvidenceBackedResult4)->Result<(),IdsInterpretationAssuranceError>{if r.schema_version!=INPUT_SCHEMA||r.request_id.trim().is_empty()||r.researcher.trim().is_empty()||r.purpose.trim().is_empty()||r.semantic_profile.trim().is_empty()||r.required_study_order.is_empty()||r.required_modality_order.is_empty()||!ordered(&r.required_study_order)||!ordered(&r.required_modality_order)||!ordered(&r.adversarial_event_order)||!hash(&r.comparability_digest)||!hash(&r.replay_identity)||r.candidates.is_empty()||!r.raw_data_local||!r.aggregate_only||r.boundary!=PRECLINICAL_BOUNDARY{return Err(IdsInterpretationAssuranceError::Invalid("interpretation identity, requirements, digests, locality, or boundary is invalid".into()))}let mut ids=BTreeSet::new();for c in &r.candidates{if c.candidate_id.trim().is_empty()||!ids.insert(c.candidate_id.clone())||c.study_order.is_empty()||c.modality_order.is_empty()||!ordered(&c.study_order)||!ordered(&c.modality_order)||c.semantic_profile.trim().is_empty()||c.interpretation_score_milli>1000||!hash(&c.comparability_digest)||!hash(&c.result_digest)||!hash(&c.provenance_digest)||!hash(&c.replay_identity)||!ordered(&c.omission_order)||!ordered(&c.uncertainty_order){return Err(IdsInterpretationAssuranceError::Invalid("candidate identity, axes, score, digest, or ordering is invalid".into()))}}Ok(())}
impl IdsInteractiveInterpretation7{pub fn validate(&self)->Result<(),IdsInterpretationAssuranceError>{if self.schema_version!="aurora-research-contract/1.0"||self.contract_version!=CONTRACT_VERSION||self.feature_id!=FEATURE_ID||self.boundary!=PRECLINICAL_BOUNDARY||self.artifact.boundary!=PRECLINICAL_BOUNDARY||self.artifact.content_type!=CONTENT_TYPE||!self.raw_data_local||!self.aggregate_only||self.request_id.trim().is_empty()||self.researcher.trim().is_empty()||self.purpose.trim().is_empty()||self.semantic_profile.trim().is_empty()||self.candidate_order.is_empty()||self.effect_receipts.is_empty(){return Err(IdsInterpretationAssuranceError::Output("interpretation identity, locality, candidates, or release gate is incomplete".into()))}for v in [&self.candidate_order,&self.qualified_order,&self.unresolved_order,&self.blocked_order,&self.incomparable_order,&self.missing_study_order,&self.missing_modality_order,&self.omission_order,&self.uncertainty_order,&self.negative_evidence_order,&self.effect_receipts]{if !ordered(v){return Err(IdsInterpretationAssuranceError::Output("interpretation ordering is not canonical".into()))}}let ids=self.candidate_order.iter().cloned().collect::<BTreeSet<_>>();let parts=self.qualified_order.iter().chain(&self.unresolved_order).chain(&self.blocked_order).chain(&self.incomparable_order).cloned().collect::<Vec<_>>();if ids.len()!=self.candidate_order.len()||parts.len()!=ids.len()||BTreeSet::from_iter(parts)!=ids{return Err(IdsInterpretationAssuranceError::Output("interpretation states do not partition candidates".into()))}if !hash(&self.replay_identity)||!hash(&self.interpretation_digest)||self.artifact.content_hash!=self.interpretation_digest||self.artifact.provenance_digests.iter().any(|d|!hash(d)){return Err(IdsInterpretationAssuranceError::Output("interpretation digest or artifact metadata is invalid".into()))}if self.disposition=="qualified"&&!self.effect_receipts.iter().any(|e|e.starts_with("verify:ids-interpretation:")){return Err(IdsInterpretationAssuranceError::Output("qualified interpretation effect is invalid".into()))}if self.disposition!="qualified"&&self.effect_receipts!=vec!["block:unsafe-release"]{return Err(IdsInterpretationAssuranceError::Output("non-qualified interpretation must block release".into()))}Ok(())}pub fn digest(&self)->Result<ContentHash,IdsInterpretationAssuranceError>{self.validate()?;ContentHash::of_value(&serde_json::to_value(self).map_err(|e|IdsInterpretationAssuranceError::Output(e.to_string()))?).map_err(|e|IdsInterpretationAssuranceError::Output(e.to_string()))}}
pub fn assure_ids_interpretation(r:&IdsEvidenceBackedResult4)->Result<IdsInteractiveInterpretation7,IdsInterpretationAssuranceError>{validate_request(r)?;let mut rows=r.candidates.clone();rows.sort_by(|a,b|b.interpretation_score_milli.cmp(&a.interpretation_score_milli).then(a.candidate_id.cmp(&b.candidate_id)));let ids=rows.iter().map(|c|c.candidate_id.clone()).collect::<Vec<_>>();let mut q=BTreeSet::new();let mut u=BTreeSet::new();let mut b=BTreeSet::new();let mut inc=BTreeSet::new();let mut miss_study=BTreeSet::new();let mut miss_mod=BTreeSet::new();let mut om=BTreeSet::new();let mut un=BTreeSet::new();let mut neg=BTreeSet::new();let mut prov=BTreeSet::new();for c in &rows{let id=c.candidate_id.clone();prov.insert(c.provenance_digest.clone());om.extend(c.omission_order.iter().map(|x|format!("{id}:{x}")));un.extend(c.uncertainty_order.iter().map(|x|format!("{id}:{x}")));if c.negative_result||c.evidence_state==IdsInterpretationEvidenceState::Negative{neg.insert(format!("{id}:negative-result"));}if !c.local||!c.aggregate_only||!c.policy_allowed||c.replay_identity!=r.replay_identity{b.insert(id.clone());}else if r.required_study_order.iter().any(|x|!c.study_order.contains(x)){miss_study.extend(r.required_study_order.iter().filter(|x|!c.study_order.contains(x)).map(|x|format!("{id}:{x}")));inc.insert(id.clone());}else if r.required_modality_order.iter().any(|x|!c.modality_order.contains(x)){miss_mod.extend(r.required_modality_order.iter().filter(|x|!c.modality_order.contains(x)).map(|x|format!("{id}:{x}")));inc.insert(id.clone());}else if c.comparability_digest!=r.comparability_digest{inc.insert(id.clone());un.insert(format!("{id}:comparability-mismatch"));}else if !matches!(c.evidence_state,IdsInterpretationEvidenceState::Proven|IdsInterpretationEvidenceState::Supported)||c.interpretation_score_milli<600{u.insert(id.clone());}else{q.insert(id.clone());}}let global=!r.policy_allowed||!r.protected_closure||!r.signed_approval||!r.federation_allowed||!r.raw_data_local||!r.aggregate_only||!r.adversarial_event_order.is_empty();if global{b.extend(ids.iter().cloned());q.clear();u.clear();inc.clear();om.insert("request:governance-or-adversarial-blocked".into());}un.extend(r.adversarial_event_order.iter().map(|e|format!("adversarial:{e}")));let qo=q.iter().cloned().collect::<Vec<_>>();let uo=u.iter().cloned().collect::<Vec<_>>();let bo=b.iter().cloned().collect::<Vec<_>>();let io=inc.iter().cloned().collect::<Vec<_>>();let disp=if global{"blocked"}else if !uo.is_empty()||!bo.is_empty()||!io.is_empty(){"unresolved"}else{"qualified"};if disp!="qualified"{om.insert("request:interpretation-closure-not-ready".into());}let mut payload=json!({"schema_version":"aurora-research-contract/1.0","contract_version":CONTRACT_VERSION,"feature_id":FEATURE_ID,"request_id":r.request_id,"researcher":r.researcher,"purpose":r.purpose,"semantic_profile":r.semantic_profile,"disposition":disp,"candidate_order":ids,"qualified_order":qo,"unresolved_order":uo,"blocked_order":bo,"incomparable_order":io,"missing_study_order":miss_study.iter().cloned().collect::<Vec<_>>(),"missing_modality_order":miss_mod.iter().cloned().collect::<Vec<_>>(),"omission_order":om.iter().cloned().collect::<Vec<_>>(),"uncertainty_order":un.iter().cloned().collect::<Vec<_>>(),"negative_evidence_order":neg.iter().cloned().collect::<Vec<_>>(),"replay_identity":r.replay_identity,"raw_data_local":true,"aggregate_only":true,"boundary":PRECLINICAL_BOUNDARY});let d=ContentHash::of_value(&payload).map_err(|e|IdsInterpretationAssuranceError::Output(e.to_string()))?;payload["interpretation_digest"]=json!(d);payload["artifact"]=json!({"artifact_id":format!("interactive-interpretation-7:{}",r.request_id),"content_type":CONTENT_TYPE,"content_hash":d,"semantic_loss":payload["omission_order"],"provenance_digests":prov.iter().cloned().collect::<Vec<_>>(),"boundary":PRECLINICAL_BOUNDARY});payload["effect_receipts"]=if disp=="qualified"{json!([format!("verify:ids-interpretation:{}",r.request_id)])}else{json!(["block:unsafe-release"])};let out:IdsInteractiveInterpretation7=serde_json::from_value(payload).map_err(|e|IdsInterpretationAssuranceError::Output(e.to_string()))?;out.validate()?;Ok(out)}
#[cfg(test)]mod tests{use super::*;fn h(v:&str)->ContentHash{ContentHash::of_bytes(v.as_bytes())}fn c()->IdsInterpretationCandidate4{IdsInterpretationCandidate4{candidate_id:"c".into(),study_order:vec!["s".into()],modality_order:vec!["imaging".into()],semantic_profile:"ome".into(),interpretation_score_milli:800,evidence_state:IdsInterpretationEvidenceState::Supported,comparability_digest:h("cmp"),result_digest:h("res"),provenance_digest:h("p"),replay_identity:h("r"),local:true,aggregate_only:true,policy_allowed:true,omission_order:vec![],uncertainty_order:vec![],negative_result:false}}fn r()->IdsEvidenceBackedResult4{IdsEvidenceBackedResult4{schema_version:INPUT_SCHEMA.into(),request_id:"q".into(),researcher:"r".into(),purpose:"p".into(),semantic_profile:"ome".into(),required_study_order:vec!["s".into()],required_modality_order:vec!["imaging".into()],comparability_digest:h("cmp"),replay_identity:h("r"),candidates:vec![c()],policy_allowed:true,protected_closure:true,signed_approval:true,federation_allowed:true,raw_data_local:true,aggregate_only:true,adversarial_event_order:vec![],boundary:PRECLINICAL_BOUNDARY.into()}}#[test]fn qualified_emits_verification(){assert!(assure_ids_interpretation(&r()).unwrap().effect_receipts[0].starts_with("verify:ids-interpretation:"))}#[test]fn missing_modality_is_retained(){let mut x=r();x.required_modality_order=vec!["omics".into()];assert!(!assure_ids_interpretation(&x).unwrap().missing_modality_order.is_empty())}#[test]fn adversarial_blocks(){let mut x=r();x.adversarial_event_order=vec!["prompt-injection".into()];assert_eq!(assure_ids_interpretation(&x).unwrap().disposition,"blocked")} }



